function LearningNodeEvidence({node,state,learning,selected=false}:{node:LearningPathNode;state:LearningPathSequence["nodes"][number]|undefined;learning:DynamicLearningState|undefined;selected?:boolean}) {
  const content=node.learning_content??learning?.contract.learning_content;
  const contract=node.assessment_contract??learning?.contract.assessment_contract;
  const questionById=new Map((contract?.questions??[]).map(question=>[question.question_id,question]));
  return <section className="learning-node-evidence" aria-label={`${node.title} lesson and evidence`}>
    <p><strong>Assessment:</strong> {statusLabel(state?.assessment_status??"not_started")} · {state?.assessment_attempted?"attempt recorded":"not assessed"} · {state?.assessment_accepted?"accepted answer recorded":"no accepted answer"}</p>
    <p><strong>Career Forge evidence:</strong> {state?.evidence_count??0} matching record(s) · {state?.evidence_persisted?"persisted":"none yet"}</p>
    <p><strong>Mastery:</strong> {String(state?.evidence?.mastery??learning?.mastery??"unverified")} · requirement {state?.mastery_requirement??node.required_mastery??"apply_independently"} · {state?.verified_mastery?"verified":"not verified"}</p>
    <p><strong>Prerequisites:</strong> {state?.prerequisite_unlocked===false?`blocked (${state.blockers.map(id=>id).join(", ")})`:"unlocked"}. Reading and review content stays available.</p>
    {content&&<details className="learning-node-content" open={selected}><summary>Lesson, examples, and exercise</summary>
      <h4>Learning objective</h4><p>{content.explanation}</p>
      <h4>Examples</h4><ul>{content.examples.map((example,index)=><li key={`${node.node_id}-example-${index}`}>{example}</li>)}</ul>
      {content.exercise&&<><h4>Practical exercise</h4><p>{content.exercise.prompt}</p>{content.exercise.starter_code&&<pre aria-label={`${node.title} starter code`}>{content.exercise.starter_code}</pre>}</>}
      {content.remediation&&<><h4>Targeted reinforcement</h4><p>{content.remediation}</p></>}
      {contract&&<><h4>Assessment contract · {contract.contract_id} · {contract.version}</h4><ul>{contract.questions.map(question=><li key={question.question_id}><strong>{question.kind}:</strong> {question.prompt}</li>)}</ul></>}
    </details>}
    {learning&&<details className="learning-node-attempt-history" open={learning.attempts.length>0}>
      <summary>Assessment and feedback history ({learning.attempts.length}{learning.attempts_truncated?"+":""})</summary>
      {learning.attempts.length===0?<p>No assessment attempts have been recorded.</p>:<ol>{learning.attempts.map(attempt=><li key={attempt.attempt_id}>
        <p><strong>{statusLabel(attempt.assessment_status)}</strong> · {attempt.assistance_level?`assistance: ${statusLabel(attempt.assistance_level)}`:"independent attempt"}</p>
        <p><strong>Question:</strong> {questionById.get(attempt.question_id)?.prompt??attempt.question_id}</p>
        <pre aria-label={`Submitted answer ${attempt.attempt_order}`}>{attempt.response}</pre>
        {attempt.feedback&&<p><strong>Feedback:</strong> {attempt.feedback}</p>}
        <small>{attempt.evidence_id?`Career Forge evidence ${attempt.evidence_id}`:"No qualifying evidence on this attempt"}</small>
      </li>)}</ol>}{learning.attempts_truncated&&<p>Earlier attempts remain persisted in Career Forge history; the visible list is bounded to the latest 100.</p>}</details>}
  </section>;
}

